62	struct AxesInfo {
63	    int64_t b;
64	    int64_t n1;
65	    int64_t n2;
66	    int64_t s1;
67	    int64_t s2;
68	    int64_t d;
69	    int64_t dk;
70	    int64_t dv;
71	};
72	
73	enum class InputLayout {
74	    BSND,
75	    SBH,
76	    BNSD,
77	    BSH,
78	    TND
79	};
80	
81	struct FaShapeInfo {
82	    AxesInfo axes;
83	
84	    InputLayout inputLayout;
85	    string l0InputLayoutStr;
86	
87	    uint64_t dimNum = 0;
88	    uint64_t padNum = 0;
89	    uint64_t padNumv = 0;
90	
91	    FVector<int64_t, DIM_NUM_4> perm_in;
92	    FVector<int64_t, DIM_NUM_4> perm_out;
93	    FVector<int64_t, DIM_NUM_4> reshapedQueryShape;
94	    FVector<int64_t, DIM_NUM_4> reshapedKeyShape;
95	    FVector<int64_t, DIM_NUM_4> reshapedValueBefore;
96	
97	    bool needPad = false;
98	    bool needTranspose = false;
99	    bool needReshape = false;
100	    bool needPadValue = false;
101	};
102	
103	static bool StrideLimited() {
104	    NpuArch npuArch = GetCurrentPlatformInfo().GetCurNpuArch();
105	    if (npuArch == NpuArch::DAV_2201) {
106	        return true;
107	    }
108	    return false;
109	}
110	
111	static void AnalysisAxisForBsh(const Shape &qShape, const Shape &kShape, const Shape &vShape, FaShapeInfo &shapeInfo)
112	{
113	    shapeInfo.inputLayout = InputLayout::BSH;
114	    shapeInfo.l0InputLayoutStr = "BSH";
115	    shapeInfo.axes.d = qShape[2] / shapeInfo.axes.n1;
116	    shapeInfo.axes.b = qShape[0];
117	    shapeInfo.axes.n2 = shapeInfo.axes.d == 0 ? 0 : kShape[2] / shapeInfo.axes.d;
118	    shapeInfo.axes.s1 = qShape[1];
119	    shapeInfo.axes.s2 = kShape[1];
120	    shapeInfo.axes.dk = shapeInfo.axes.n2 == 0 ? shapeInfo.axes.d : kShape[2] / shapeInfo.axes.n2;
121	    shapeInfo.axes.dv = shapeInfo.axes.n2 == 0 ? shapeInfo.axes.d : vShape[2] / shapeInfo.axes.n2;
122	}
123	
124	static void AnalysisAxisForBsnd(const Shape &qShape, const Shape &kShape, const Shape &vShape, FaShapeInfo &shapeInfo)
125	{
126	    shapeInfo.inputLayout = InputLayout::BSND;
127	    shapeInfo.l0InputLayoutStr = "BSND";
128	    shapeInfo.axes.b = qShape[0];
129	    shapeInfo.axes.n2 = kShape[2];
130	    shapeInfo.axes.s1 = qShape[1];
131	    shapeInfo.axes.s2 = kShape[1];
132	    shapeInfo.axes.d = qShape[3];
133	    shapeInfo.axes.dk = kShape[3];
134	    shapeInfo.axes.dv = vShape[3];
135	}
136	
137	static void AnalysisAxisForTnd(const Shape &qShape, const Shape &kShape, const Shape &vShape, FaShapeInfo &shapeInfo)
138	{
139	    shapeInfo.inputLayout = InputLayout::TND;
140	    shapeInfo.l0InputLayoutStr = "TND";
141	    shapeInfo.axes.n2 = kShape[1];
142	    shapeInfo.axes.d = qShape[DIM_NUM_2];
143	    shapeInfo.axes.dk = kShape[DIM_NUM_2];
144	    shapeInfo.axes.dv = vShape[DIM_NUM_2];
145	}
146	
147	static void AnalysisAxisForSbh(const Shape &qShape, const Shape &kShape, const Shape &vShape, FaShapeInfo &shapeInfo)
148	{
149	    shapeInfo.inputLayout = InputLayout::SBH;
150	    shapeInfo.l0InputLayoutStr = "SBH";
151	    shapeInfo.axes.d = qShape[2] / shapeInfo.axes.n1;
152	    shapeInfo.axes.b = qShape[1];
153	    shapeInfo.axes.n2 = shapeInfo.axes.d == 0 ? 0 : kShape[2] / shapeInfo.axes.d;
154	    shapeInfo.axes.s1 = qShape[0];
155	    shapeInfo.axes.s2 = kShape[0];
156	    shapeInfo.axes.dk = shapeInfo.axes.n2 == 0 ? shapeInfo.axes.d : kShape[2] / shapeInfo.axes.n2;
157	    shapeInfo.axes.dv = shapeInfo.axes.n2 == 0 ? shapeInfo.axes.d : vShape[2] / shapeInfo.axes.n2;
158	}
159	
160	static void AnalysisAxisForBnsd(const Shape &qShape, const Shape &kShape, const Shape &vShape, FaShapeInfo &shapeInfo)
161	{
162	    shapeInfo.inputLayout = InputLayout::BNSD;
163	    shapeInfo.l0InputLayoutStr = "BNSD";
164	    shapeInfo.axes.b = qShape[0];
165	    shapeInfo.axes.n2 = kShape[1];
166	    shapeInfo.axes.s1 = qShape[2];
167	    shapeInfo.axes.s2 = kShape[2];
168	    shapeInfo.axes.d = qShape[3];
169	    shapeInfo.axes.dk = kShape[3];
170	    shapeInfo.axes.dv = vShape[3];
171	}
