173	static aclnnStatus AnalysisAxis(const aclTensor *query, const aclTensor *key, const aclTensor *value, 
174	                                const char *inputLayout, int64_t headNum, FaShapeInfo &shapeInfo)
175	{
176	    Shape qShape = query->GetViewShape();
177	    Shape kShape = key->GetViewShape();
178	    Shape vShape = value->GetViewShape();
179	    shapeInfo.dimNum = qShape.GetDimNum();
180	
181	    // 记录轴的长度 b, n2, g, s1, s2, d
182	    // H1等于N1*D, H2等于N2*D
183	    // N1等于g*N2
184	    shapeInfo.axes.n1 = headNum;
185	    std::string inputLayoutStr = op::ToString(inputLayout).GetString();
186	    for (auto &c : inputLayoutStr) {
187	        c = toupper(c);
188	    }
189	    if (shapeInfo.dimNum == DIM_NUM_3 && inputLayoutStr == "BSH") {
190	        // query: (B,S1,N1*D)
191	        // key/value: (B,S2,N2*D)
192	        AnalysisAxisForBsh(qShape, kShape, vShape, shapeInfo);
193	    } else if (shapeInfo.dimNum == DIM_NUM_4 && inputLayoutStr == "BSND") {
194	        // query: (B,S1,N1,D)
195	        // key/value: (B,S2,N2,D)
196	        AnalysisAxisForBsnd(qShape, kShape, vShape, shapeInfo);
197	    } else if (shapeInfo.dimNum == DIM_NUM_3 && inputLayoutStr == "SBH") {
198	        // query: (S1,B,N1*D)
199	        // key/value: (S2,B,N2*D)
200	        AnalysisAxisForSbh(qShape, kShape, vShape, shapeInfo);
201	    } else if (shapeInfo.dimNum == DIM_NUM_4 && inputLayoutStr == "BNSD") {
202	        // query: (B,N1,S1,D)
203	        // key/value: (B,N2,S2,D)
204	        AnalysisAxisForBnsd(qShape, kShape, vShape, shapeInfo);
205	    } else if (shapeInfo.dimNum == DIM_NUM_3 && inputLayoutStr == "TND") {
206	        // query: (T,N1,D)
207	        // key/value: (T,N2,D)
208	        AnalysisAxisForTnd(qShape, kShape, vShape, shapeInfo);
209	    } else {
210	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "not support inputLayout %s with dim_num %lu",
211	            inputLayoutStr.c_str(), shapeInfo.dimNum);
212	        return ACLNN_ERR_PARAM_INVALID;
213	    }
214	    if (shapeInfo.axes.d != shapeInfo.axes.dk) {
215	        std::string dMsg = std::to_string(shapeInfo.axes.d) + " and " + std::to_string(shapeInfo.axes.dk);
216	        std::string reason = "The values of the D dim of input query and key must be the same";
217	        OP_LOGE_FOR_INVALID_VALUES_WITH_REASON("FlashAttentionScore", "query and key", dMsg.c_str(), reason.c_str());
218	        return ACLNN_ERR_PARAM_INVALID;
219	    }
220	    if (shapeInfo.axes.d < shapeInfo.axes.dv) {
221	        std::string dMsg = std::to_string(shapeInfo.axes.d) + " and " + std::to_string(shapeInfo.axes.dv);
222	        std::string reason = "The value of D dim of input key must be greater than or equal to "
223	                             "the value of D dim of input value";
224	        OP_LOGE_FOR_INVALID_VALUES_WITH_REASON("FlashAttentionScore", "key and value", dMsg.c_str(), reason.c_str());
225	        return ACLNN_ERR_PARAM_INVALID;
226	    }
227	    return ACLNN_SUCCESS;
228	}
229	
230	static void SetShapeInfoForBshBsnd(int64_t alignedH1Size, FaShapeInfo &shapeInfo)
231	{
232	    if (alignedH1Size > MAX_STRIDE_S1) {
233	        shapeInfo.needTranspose = true;
234	        shapeInfo.needReshape = true;
235	        shapeInfo.l0InputLayoutStr = "BNSD";
236	
237	        // B,S,N,D -> B,N,S,D
238	        shapeInfo.perm_in.assign({0, 2, 1, 3});
239	        // B,N,S,D -> B,S,N,D
240	        shapeInfo.perm_out.assign(shapeInfo.perm_in.cbegin(), shapeInfo.perm_in.cend());
241	    }
242	    if (shapeInfo.needPad) {
243	        shapeInfo.needReshape = true;
244	    }
245	
246	    if (shapeInfo.inputLayout == InputLayout::BSND) {
247	        shapeInfo.needReshape = false;
248	    }
249	    if (shapeInfo.needReshape) {
250	        if (!shapeInfo.needTranspose) {
251	            shapeInfo.l0InputLayoutStr = "BSND";
252	        }
253	        shapeInfo.reshapedQueryShape.assign({shapeInfo.axes.b, shapeInfo.axes.s1, shapeInfo.axes.n1, shapeInfo.axes.d});
254	        shapeInfo.reshapedKeyShape.assign(
255	            {shapeInfo.axes.b, shapeInfo.axes.s2, shapeInfo.axes.n2, shapeInfo.axes.d});
256	        shapeInfo.reshapedValueBefore.assign({shapeInfo.axes.b, shapeInfo.axes.s2, shapeInfo.axes.n2, shapeInfo.axes.dv});
257	    }
258	}
259	
260	static void SetShapeInfoForSbh(int64_t alignedH1Size, FaShapeInfo &shapeInfo)
261	{
262	    if (shapeInfo.axes.b * alignedH1Size > MAX_STRIDE_S1) {
263	        shapeInfo.needTranspose = true;
264	        shapeInfo.needReshape = true;
265	        shapeInfo.l0InputLayoutStr = "BNSD";
266	
267	        // S,B,N,D -> B,N,S,D
268	        shapeInfo.perm_in.assign({1, 2, 0, 3});
269	        // B,N,S,D -> S,B,N,D
270	        shapeInfo.perm_out.assign({2, 0, 1, 3});
271	    }
272	    if (shapeInfo.needPad) {
273	        shapeInfo.needReshape = true;
274	    }
275	
276	    if (shapeInfo.needReshape) {
277	        if (!shapeInfo.needTranspose) {
278	            shapeInfo.l0InputLayoutStr = "SBH";
279	        }
280	        shapeInfo.reshapedQueryShape.assign({shapeInfo.axes.s1, shapeInfo.axes.b, shapeInfo.axes.n1, shapeInfo.axes.d});
281	        shapeInfo.reshapedKeyShape.assign(
282	            {shapeInfo.axes.s2, shapeInfo.axes.b, shapeInfo.axes.n2, shapeInfo.axes.d});
283	        shapeInfo.reshapedValueBefore.assign({shapeInfo.axes.s2, shapeInfo.axes.b, shapeInfo.axes.n2, shapeInfo.axes.dv});
284	    }
285	}
