287	static int64_t GetSumIntArrayMaxValue(const aclIntArray *intArrayValue)
288	{
289	    // 获取targetLengthsList中的最大值
290	    int64_t maxLength = 0;
291	    int64_t tmpMaxLength = 0;
292	    if (intArrayValue->Size() == 1) {
293	        maxLength = static_cast<int64_t>((*intArrayValue)[0]);
294	        return maxLength;
295	    }
296	    maxLength = static_cast<int64_t>((*intArrayValue)[0]);
297	    for (size_t i = 1; i < intArrayValue->Size(); ++i) {
298	        tmpMaxLength = static_cast<int64_t>((*intArrayValue)[i]) - static_cast<int64_t>((*intArrayValue)[i - 1]);
299	        if (tmpMaxLength > maxLength) {
300	            maxLength = tmpMaxLength;
301	        }
302	    }
303	    return maxLength;
304	}
305	
306	static int64_t getSeqLenQSum(const aclIntArray *actualSeqQLenOptional) {
307	    if (actualSeqQLenOptional->Size() < 1) {
308	        return 0;
309	    }
310	    int64_t sQLenSum = 0;
311	    for (int64_t i = actualSeqQLenOptional->Size() - 1; i >= 0; --i) {
312	        sQLenSum = static_cast<int64_t>((*actualSeqQLenOptional)[i]);
313	        if (sQLenSum > 0) {
314	            break;
315	        }
316	    }
317	    return sQLenSum;
318	}
319	
320	static bool IsNeedPad(FaShapeInfo &shapeInfo, const aclIntArray *actualSeqQLenOptional,
321	                      const aclIntArray *actualSeqKvLenOptional)
322	{
323	    if (shapeInfo.inputLayout != InputLayout::BNSD &&
324	         shapeInfo.inputLayout != InputLayout::TND && shapeInfo.axes.n1 == shapeInfo.axes.n2 &&
325	         shapeInfo.needTranspose == false) {
326	        if (shapeInfo.axes.d == HEAD_DIM_72 || shapeInfo.axes.d == HEAD_DIM_88) {
327	            shapeInfo.padNum = 0;
328	        }
329	        if (shapeInfo.axes.dv == HEAD_DIM_72 || shapeInfo.axes.dv == HEAD_DIM_88) {
330	            shapeInfo.padNumv = 0;
331	        }
332	        if ((shapeInfo.axes.d == HEAD_DIM_72 || shapeInfo.axes.d == HEAD_DIM_88) 
333	                && (shapeInfo.axes.dv == HEAD_DIM_72 || shapeInfo.axes.dv == HEAD_DIM_88)) {
334	            return false;
335	        }
336	        return true;
337	    }
338	
339	    if (shapeInfo.inputLayout == InputLayout::TND) {
340	        if (shapeInfo.axes.d >= TND_UNPAD_MAX_DDIM) {
341	            return true;
342	        }
343	        int64_t sKvLenMax = 0;
344	        int64_t sQLenSum = 0;
345	        if (actualSeqQLenOptional != nullptr && actualSeqKvLenOptional != nullptr &&
346	            actualSeqQLenOptional->Size() == actualSeqKvLenOptional->Size()) {
347	            sKvLenMax = GetSumIntArrayMaxValue(actualSeqKvLenOptional);
348	            sQLenSum = getSeqLenQSum(actualSeqQLenOptional);
349	        }
350	
351	        if (sKvLenMax == 0 || sQLenSum == 0) {
352	            // 走原来逻辑是否pad
353	            OP_LOGD("Fa aclnn TND case sKvLenMax(%ld) or sQLenSum(%ld) is 0.", sKvLenMax, sQLenSum);
354	            return true;
355	        }
356	
357	        if ((sKvLenMax <= TND_UNPAD_MAX_S2) && (sQLenSum < TND_UNPAD_MAX_S1_SUM)) {
358	            // 去除pad
359	            OP_LOGD("Fa aclnn TND case do not do pad dimD operation.");
360	            shapeInfo.padNum = 0;
361	            shapeInfo.padNumv = 0;
362	            return false;
363	        }
364	    }
365	    return true;
366	}
367	
368	static bool IsCapableSameAB(const FaShapeInfo &shapeInfo, const aclTensor *query)
369	{
370	    if (query->GetDataType() == op::DataType::DT_FLOAT) {
371	        return false;
372	    }
373	    if (((shapeInfo.axes.d + shapeInfo.padNum) % FRACTAL_NUM != 0 || shapeInfo.axes.d == D_SPECIFIC_SIZE_96) && (shapeInfo.axes.s2 >= S2_REUSE_SIZE_512)) {
374	        return true;
375	    }
376	    if (shapeInfo.axes.s2 > s2sizeLimitMin && shapeInfo.axes.d > SAMEAB_D_LIMIT_128 && shapeInfo.axes.d < SAMEAB_D_LIMIT_196) {
377	        return true;
378	    }
379	    return false;
380	}
381	
382	static bool isSupportMLA(const FaShapeInfo &shapeInfo, const aclTensor *query)
383	{
384	    // TND模板支持MLA
385	    if(shapeInfo.inputLayout == InputLayout::TND) {
386	        return true;
387	    }
388	    // SameAB模板支持MLA
389	    if(IsCapableSameAB(shapeInfo, query)) {
390	        return true;
391	    }
392	    // S1S2模板支持MLA
393	    if (shapeInfo.axes.s2 > s2sizeLimitMin) {
394	        return true;
395	    }
396	    return false;
397	}
