399	static aclnnStatus InputOutputDtypeCheck(const aclTensor *query, const aclTensor *attentionOut)
400	{
401	    auto qDtype = query->GetDataType();
402	    auto outDtype = attentionOut->GetDataType();
403	    if (qDtype != outDtype) {
404	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "Input query tensor's dtype should be same with attentionOut tensor's dtype");
405	        return ACLNN_ERR_PARAM_INVALID;
406	    }
407	    return ACLNN_SUCCESS;
