410	static aclnnStatus InputDtypeCheck(const aclTensor *query, const aclTensor *key, const aclTensor *value,
411	                                   const aclTensor *attentionOut, const aclTensor *realShiftOptional,
412	                                   int64_t pseType, const aclTensor *sinkOptional)
413	{
414	    auto vDtype = value->GetDataType();
415	    auto kDtype = key->GetDataType();
416	    auto qDtype = query->GetDataType();
417	    auto outDtype = attentionOut->GetDataType();
418	    if (qDtype != kDtype || kDtype != vDtype) {
419	        std::string paramMsg = "query, key and value";
420	        std::string dtypeMsg = std::string(op::ToString(DataType(qDtype)).GetString()) + ", " +
421	            op::ToString(DataType(kDtype)).GetString() + " and " +
422	            op::ToString(DataType(vDtype)).GetString();
423	        OP_LOGE_FOR_INVALID_DTYPES_WITH_REASON(op::internal::GetLogApiInfo().c_str(), paramMsg.c_str(),
424	            dtypeMsg.c_str(), "The dtypes of input query, key and value must be the same");
425	        return ACLNN_ERR_PARAM_INVALID;
426	    }
427	
428	    if (StrideLimited() &&
429	        !(qDtype == op::DataType::DT_FLOAT || qDtype == op::DataType::DT_FLOAT16 || qDtype == op::DataType::DT_BF16)) {
430	        std::string dtypeStr = op::ToString(DataType(qDtype)).GetString();
431	        OP_LOGE_FOR_INVALID_DTYPES_WITH_REASON(op::internal::GetLogApiInfo().c_str(),
432	            "query, key and value", dtypeStr.c_str(),
433	            "The dtypes of input query, key and value must be within the range {FLOAT, FLOAT16, BF16}");
434	        return ACLNN_ERR_PARAM_INVALID;
435	    }
436	    if (pseType == PSE_INNER_MUL_ADD || pseType == PSE_INNER_MUL_ADD_SQRT) {
437	        // Inner pse alibi, dtype must be fp32
438	        if (realShiftOptional == nullptr) {
439	            OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "When pseType is 2 or 3, pseShape cannot be null.");
440	            return ACLNN_ERR_PARAM_NULLPTR;
441	        }
442	        auto pseDtype = realShiftOptional->GetDataType();
443	        if (pseDtype != op::DataType::DT_FLOAT) {
444	            std::string dtypeStr = op::ToString(DataType(pseDtype)).GetString();
445	            OP_LOGE_FOR_INVALID_DTYPE_WITH_REASON(op::internal::GetLogApiInfo().c_str(), "pse",
446	                dtypeStr.c_str(), "The dtype of input pse must be FLOAT when the mode of pse is 2 or 3");
447	            return ACLNN_ERR_PARAM_INVALID;
448	        }
449	        return ACLNN_SUCCESS;
450	    }
451	    if (realShiftOptional != nullptr) {
452	        auto pseDtype = realShiftOptional->GetDataType();
453	        if (pseDtype != outDtype) {
454	            std::string paramMsg = "pse and attentionOut";
455	            std::string dtypeMsg = std::string(op::ToString(DataType(pseDtype)).GetString()) + " and " +
456	                op::ToString(DataType(outDtype)).GetString();
457	            OP_LOGE_FOR_INVALID_DTYPES_WITH_REASON(op::internal::GetLogApiInfo().c_str(), paramMsg.c_str(),
458	                dtypeMsg.c_str(), "The dtypes of input pse and output attentionOut must be the same");
459	            return ACLNN_ERR_PARAM_INVALID;
460	        }
461	    }
462	    if (sinkOptional != nullptr) {
463	        auto sinkDtype = sinkOptional->GetDataType();
464	        if (sinkDtype != op::DataType::DT_FLOAT) {
465	            std::string dtypeStr = op::ToString(DataType(sinkDtype)).GetString();
466	            OP_LOGE_WITH_INVALID_INPUT_DTYPE(op::internal::GetLogApiInfo().c_str(), "sink",
467	                dtypeStr.c_str(), "FLOAT");
468	            return ACLNN_ERR_PARAM_INVALID;
469	        }
470	    }
471	    return ACLNN_SUCCESS;
472	}
