502	static inline bool CheckFormat(
503	    const aclTensor *query, const aclTensor *queryRope, const aclTensor *key, const aclTensor *keyRope, const aclTensor *value, const aclTensor *realShiftOptional,
504	    const aclTensor *dropMaskOptional, const aclTensor *paddingMaskOptional, const aclTensor *attenMaskOptional, const aclTensor *sinkOptional, 
505	    const aclTensor *softmaxMaxOut, const aclTensor *softmaxSumOut, const aclTensor *attentionOutOut)
506	{
507	    bool formatValid = query->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ &&
508	                       key->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ &&
509	                       value->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ &&
510	                       softmaxMaxOut->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ &&
511	                       softmaxSumOut->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ &&
512	                       attentionOutOut->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ;
513	    if (!formatValid) {
514	        std::string formatMsg = op::ToString(query->GetStorageFormat()).GetString() + std::string(", ") +
515	            op::ToString(key->GetStorageFormat()).GetString() + std::string(", ") +
516	            op::ToString(value->GetStorageFormat()).GetString() + std::string(", ") +
517	            op::ToString(softmaxMaxOut->GetStorageFormat()).GetString() + std::string(", ") +
518	            op::ToString(softmaxSumOut->GetStorageFormat()).GetString() + std::string(", ") +
519	            op::ToString(attentionOutOut->GetStorageFormat()).GetString();
520	        OP_LOGE_FOR_INVALID_FORMATS_WITH_REASON("FlashAttentionScore",
521	            "query, key, value, softmax_max, softmax_sum and attention_out",
522	            formatMsg.c_str(), "The format of input and output should not be NZ");
523	        return false;
524	    }
525	    if (queryRope != nullptr) {
526	        formatValid = (formatValid && queryRope->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ);
527	    }
528	    if (keyRope != nullptr) {
529	        formatValid = (formatValid && keyRope->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ);
530	    }
531	    if (realShiftOptional != nullptr) {
532	        formatValid = (formatValid && realShiftOptional->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ);
533	    }
534	    if (dropMaskOptional != nullptr) {
535	        formatValid = (formatValid && dropMaskOptional->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ);
536	    }
537	    if (paddingMaskOptional != nullptr) {
538	        formatValid = (formatValid && paddingMaskOptional->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ);
539	    }
540	    if (attenMaskOptional != nullptr) {
541	        formatValid = (formatValid && attenMaskOptional->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ);
542	    }
543	    if (sinkOptional != nullptr) {
544	        formatValid = (formatValid && sinkOptional->GetStorageFormat() != op::Format::FORMAT_FRACTAL_NZ);
545	    }
546	    if (!formatValid) {
547	        std::string formatMsg = op::ToString(queryRope->GetStorageFormat()).GetString() + std::string(", ") +
548	            op::ToString(keyRope->GetStorageFormat()).GetString() + std::string(", ") +
549	            op::ToString(realShiftOptional->GetStorageFormat()).GetString() + std::string(", ") +
550	            op::ToString(dropMaskOptional->GetStorageFormat()).GetString() + std::string(", ") +
551	            op::ToString(paddingMaskOptional->GetStorageFormat()).GetString() + std::string(", ") +
552	            op::ToString(attenMaskOptional->GetStorageFormat()).GetString() + std::string(", ") +
553	            op::ToString(sinkOptional->GetStorageFormat()).GetString();
554	        OP_LOGE_FOR_INVALID_FORMATS_WITH_REASON("FlashAttentionScore",
555	            "query_rope, key_rope, real_shift, drop_mask, padding_mask, atten_mask and sink",
556	            formatMsg.c_str(), "The format of optional inputs should not be NZ");
557	        return false;
558	    }
559	    return formatValid;
560	}

