562	static aclnnStatus ShapeCheck(const aclTensor *query, const aclTensor *key, char *inputLayout)
563	{
564	    size_t layoutLen = strlen(inputLayout);
565	    if (query->GetViewShape().GetDimNum() != layoutLen || key->GetViewShape().GetDimNum() != layoutLen) {
566	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "FlashAttentionScore query or key Invalid layout");
567	        return ACLNN_ERR_PARAM_INVALID;
568	    }
569	    return ACLNN_SUCCESS;
570	}
