572	static aclnnStatus AnalysisInput(const aclTensor *query, const aclTensor *key, const aclTensor *value,
573	                                 char *inputLayout, int64_t headNum, FaShapeInfo &shapeInfo,
574	                                 const aclIntArray *actualSeqQLenOptional = nullptr,
575	                                 const aclIntArray *actualSeqKvLenOptional = nullptr)
576	{
577	    if (headNum <= 0) {
578	        OP_LOGE_FOR_INVALID_VALUE_WITH_REASON(
579	            "FlashAttentionScore", "headNum", std::to_string(headNum), "The value of headNum must be greater than 0");
580	        return ACLNN_ERR_PARAM_INVALID;
581	    }
582	    CHECK_RET(
583	        AnalysisAxis(query, key, value, inputLayout, headNum, shapeInfo) == ACLNN_SUCCESS, ACLNN_ERR_PARAM_INVALID);
584	
585	    if (shapeInfo.axes.d > HEAD_DIM_MAX) {
586	        OP_LOGE_FOR_INVALID_VALUE_WITH_REASON("FlashAttentionScore", "D dim",
587	            std::to_string(shapeInfo.axes.d).c_str(), "The value of D dim can only be in the range of (0, 768]");
588	        return ACLNN_ERR_PARAM_INVALID;
589	    }
590	
591	    if ((actualSeqQLenOptional != nullptr && actualSeqKvLenOptional != nullptr) && 
592	                    (actualSeqQLenOptional->Size() > MAX_VAR_LEN_SEQ_LEN || 
593	                    actualSeqKvLenOptional->Size() > MAX_VAR_LEN_SEQ_LEN)) {
594	        OP_LOGW("The input parameter exceeds the operator range, unknown risks exist: " 
595	               "actualSeqQLen size and actualSeqKvLen size must <= 20000, but got %lu.", actualSeqQLenOptional->Size());
596	    }
597	
598	    if (shapeInfo.axes.n2 == 0 || shapeInfo.axes.d == 0) {
599	        return ACLNN_SUCCESS;
600	    }
601	
602	    if (shapeInfo.inputLayout != InputLayout::TND &&
603	        (shapeInfo.axes.b == 0 || shapeInfo.axes.s1 == 0 || shapeInfo.axes.s2 == 0)) {
604	        return ACLNN_SUCCESS;
605	    }
606	
607	    if (!StrideLimited()) {
608	        return ACLNN_SUCCESS;
609	    }
610	
611	    int64_t alignDim = (shapeInfo.axes.d < PAD_LOWER_BOUND_196 || shapeInfo.axes.d == PAD_ALIGN_SPL_SHAPE) ?
612	                        PAD_BASIC_BLOCK : PAD_ALIGN_128;
613	    if (shapeInfo.axes.d % alignDim != 0 || shapeInfo.axes.dv % alignDim != 0) {
614	        shapeInfo.needPad = true;
615	        shapeInfo.padNum = (shapeInfo.axes.d + alignDim - 1) / alignDim * alignDim - shapeInfo.axes.d;
616	        shapeInfo.padNumv = (shapeInfo.axes.dv + alignDim - 1) / alignDim * alignDim - shapeInfo.axes.dv;
617	    }
618	
619	    // 硬件亲和dim适配
620	    if ((shapeInfo.axes.d != shapeInfo.axes.dv) &&
621	        (shapeInfo.axes.d == HEAD_DIM_128 || shapeInfo.axes.d == HEAD_DIM_64 || shapeInfo.axes.d == HEAD_DIM_80)) {
622	        shapeInfo.needPad = true;
623	        shapeInfo.padNumv = shapeInfo.padNum + shapeInfo.axes.d - shapeInfo.axes.dv;
624	    }
625	
626	    int64_t alignedH1Size = shapeInfo.axes.n1 * (shapeInfo.axes.d + shapeInfo.padNum);
627	    if (shapeInfo.inputLayout == InputLayout::BSH || shapeInfo.inputLayout == InputLayout::BSND) {
628	        SetShapeInfoForBshBsnd(alignedH1Size, shapeInfo);
629	    } else if (shapeInfo.inputLayout == InputLayout::SBH) {
630	        SetShapeInfoForSbh(alignedH1Size, shapeInfo);
631	    }
632	
633	    if (!IsNeedPad(shapeInfo, actualSeqQLenOptional, actualSeqKvLenOptional)) {
634	        shapeInfo.needPad = false;
635	        shapeInfo.needReshape = false;
636	        if (shapeInfo.inputLayout == InputLayout::BSH) {
637	            shapeInfo.l0InputLayoutStr = "BSH";
638	        }
639	    }
640	
641	    if ((shapeInfo.axes.d != shapeInfo.axes.dv) && (!isSupportMLA(shapeInfo, query))) {
642	        shapeInfo.needPadValue = true;
643	        shapeInfo.needPad = true;
644	        if (shapeInfo.inputLayout == InputLayout::SBH || shapeInfo.inputLayout == InputLayout::BSH) {
645	            shapeInfo.needReshape = true;
646	        }
647	        if (shapeInfo.inputLayout == InputLayout::BSH && !shapeInfo.needTranspose) {
648	            shapeInfo.l0InputLayoutStr = "BSND";
649	        }
650	        shapeInfo.padNumv = shapeInfo.padNum + shapeInfo.axes.d - shapeInfo.axes.dv;
651	        if (shapeInfo.inputLayout == InputLayout::BSH) {
652	            shapeInfo.reshapedQueryShape.assign({shapeInfo.axes.b, shapeInfo.axes.s1, shapeInfo.axes.n1, shapeInfo.axes.d});
653	            shapeInfo.reshapedKeyShape.assign({shapeInfo.axes.b, shapeInfo.axes.s2, shapeInfo.axes.n2, shapeInfo.axes.d});
654	            shapeInfo.reshapedValueBefore.assign({shapeInfo.axes.b, shapeInfo.axes.s2, shapeInfo.axes.n2, shapeInfo.axes.dv});
655	        }
656	        if (shapeInfo.inputLayout == InputLayout::SBH) {
657	            shapeInfo.reshapedQueryShape.assign({shapeInfo.axes.s1, shapeInfo.axes.b, shapeInfo.axes.n1, shapeInfo.axes.d});
658	            shapeInfo.reshapedKeyShape.assign({shapeInfo.axes.s2, shapeInfo.axes.b, shapeInfo.axes.n2, shapeInfo.axes.d});
659	            shapeInfo.reshapedValueBefore.assign({shapeInfo.axes.s2, shapeInfo.axes.b, shapeInfo.axes.n2, shapeInfo.axes.dv});
660	        }
661	    }
662	
663	    OP_LOGD("Analysis input success. Analysis result: [needReshape]: %d, [needPad]: %d, [padNum]: %lu, [padNumv]: %lu,"
664	            "[needTranspose]: %d, [needPadValue]: %d.",
665	            shapeInfo.needReshape, shapeInfo.needPad, shapeInfo.padNum, shapeInfo.padNumv, shapeInfo.needTranspose, shapeInfo.needPadValue);
666	    return ACLNN_SUCCESS;
667	}
