669	static inline const aclTensor *GeneratePaddings(int32_t dimNum, int32_t padNum, aclOpExecutor *executor)
670	{
671	    // 2代表每根轴的前后都可以补0
672	    FVector<int64_t> padVec(dimNum * 2, 0);
673	    padVec[padVec.size() - 1] = padNum;
674	
675	    auto padArray = executor->AllocIntArray(padVec.data(), padVec.size());
676	    if (padArray == nullptr) {
677	        OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "Try alloc padVec failed");
678	        return nullptr;
679	    }
680	
681	    auto padTensor = executor->ConvertToTensor(padArray, DataType::DT_INT64);
682	    return padTensor;
683	}
