685	static aclnnStatus Contiguous(const aclTensor *&query, const aclTensor *&key, const aclTensor *&value,
686	                              const aclTensor *&realShiftOptional, const aclTensor *&dropMaskOptional,
687	                              const aclTensor *&paddingMaskOptional, const aclTensor *&attenMaskOptional,
688	                              const aclTensor *&queryRope, const aclTensor *&keyRope, const aclTensor *&sinkOptional,
689	                              const aclTensor *&dScaleQOptional, const aclTensor *&dScaleKOptional,
690	                              const aclTensor *&dScaleVOptional, aclOpExecutor *executor)
691	{
692	    query = l0op::Contiguous(query, executor);
693	    OP_CHECK(query != nullptr,
694	        OP_LOGE_FOR_INVALID_ARGUMENT_WITH_REASON(op::internal::GetLogApiInfo().c_str(), "query",
695	            "Try contiguous query failed, query cannot be nullptr"),
696	        return ACLNN_ERR_PARAM_NULLPTR);
697	    key = l0op::Contiguous(key, executor);
698	    OP_CHECK(key != nullptr,
699	        OP_LOGE_FOR_INVALID_ARGUMENT_WITH_REASON(op::internal::GetLogApiInfo().c_str(), "key",
700	            "Try contiguous key failed, key cannot be nullptr"),
701	        return ACLNN_ERR_PARAM_NULLPTR);
702	    value = l0op::Contiguous(value, executor);
703	    OP_CHECK(value != nullptr,
704	        OP_LOGE_FOR_INVALID_ARGUMENT_WITH_REASON(op::internal::GetLogApiInfo().c_str(), "value",
705	            "Try contiguous value failed, value cannot be nullptr"),
706	        return ACLNN_ERR_PARAM_NULLPTR);
707	    if (realShiftOptional) {
708	        realShiftOptional = l0op::Contiguous(realShiftOptional, executor);
